// Monta a requisição do Jev: estado + 4 perguntas tipadas, numa chamada só (fan-out).
// LGPD / minimização: id e e-mail do aluno ficam no n8n. O Jev recebe só o que a decisão precisa.

const QUESTIONS = {
  rota: {
    type: 'choice',
    instructions: 'Para qual fila da Flowgrammers esta conversa deve ir agora?',
    criteria: {
      suporte_tecnico: 'Erro ou dúvida técnica concreta em n8n, agentes de IA, Claude Code, código ou infraestrutura do aluno',
      acesso_plataforma: 'Login, acesso a aulas, certificado, matrícula, live ou instabilidade da plataforma Flowgrammers',
      comercial: 'Quer comprar, fazer upgrade, turma para empresa, preço ou proposta',
      conteudo: 'Sugestão de aula, feedback sobre conteúdo ou dúvida conceitual sem erro concreto',
      indefinido: 'A conversa não traz informação suficiente para decidir a fila'
    }
  },
  urgencia: {
    type: 'score',
    instructions: 'Qual a urgência deste atendimento?',
    criteria: [
      'Nenhuma: cumprimento, elogio ou sugestão',
      'Baixa: pode esperar até 2 dias úteis',
      'Média: atrapalha o estudo, mas existe contorno',
      'Alta: impede o aluno de continuar',
      'Crítica: sistema em produção parado ou cliente do aluno impactado'
    ]
  },
  risco_churn: {
    type: 'noul',
    instructions: 'O aluno demonstra frustração forte ou intenção de cancelar, pedir reembolso ou abandonar o curso?'
  },
  intencao_compra: {
    type: 'noul',
    instructions: 'Há sinais consistentes de intenção de compra (novo curso, upgrade ou turma para empresa)? Uma pergunta genérica isolada sobre preço não conta.'
  }
};

return $input.all().map((item, i) => {
  const src = item.json.body ?? item.json;          // o Webhook entrega o payload em body
  const aluno = src.aluno ?? {};
  const mensagens = (src.mensagens ?? []).slice(-10).map(m => ({
    de: m.de === 'suporte' ? 'suporte' : 'aluno',
    texto: String(m.texto ?? '').slice(0, 2000)
  }));
  const state = {
    canal: src.canal ?? 'desconhecido',
    produto: aluno.produto ?? null,
    aluno_desde: aluno.aluno_desde ?? null,
    mensagens
  };
  return {
    json: {
      aluno_id: aluno.id ?? null,                    // fica no n8n, não vai pro Jev
      canal: state.canal,
      ultima_mensagem: mensagens.filter(m => m.de === 'aluno').at(-1)?.texto ?? '',
      jev_request: { model: 'jev-latest', state, questions: QUESTIONS }
    },
    pairedItem: i
  };
});

// Valida o contrato da resposta e transforma probabilidade em decisão de negócio.
// Regra de ouro: resposta fora do contrato, ou Jev fora do ar, vai pro humano. Nunca pra ação automática.

const LIMIAR_AUTO   = 0.85;  // >= executa sozinho
const LIMIAR_S2     = 0.60;  // >= Claude rascunha e humano revisa; abaixo: fila humana
const LIMIAR_ALERTA = 0.70;  // evasão / compra
const ROTAS = ['suporte_tecnico', 'acesso_plataforma', 'comercial', 'conteudo', 'indefinido'];

const req = $('Monta state (Jev)').item.json;
const res = $json;
const a = res.answers ?? {};

const num01 = v => (typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1 ? v : null);

function choiceValida(ans, ids) {
  if (!ans || !ids.includes(ans.choice)) return false;
  const p = ans.probabilities ?? {};
  if (Object.keys(p).sort().join('|') !== [...ids].sort().join('|')) return false;
  const vals = Object.values(p);
  if (vals.some(v => num01(v) === null)) return false;
  if (Math.abs(vals.reduce((x, y) => x + y, 0) - 1) > 0.02) return false;
  if (p[ans.choice] < Math.max(...vals) - 1e-6) return false;
  return num01(ans.confidence) !== null;
}

const valida = choiceValida(a.rota, ROTAS);
const rota = valida ? a.rota.choice : 'indefinido';
const confianca = valida ? a.rota.confidence : 0;
const urgencia = typeof a.urgencia?.score === 'number' ? a.urgencia.score : null;
const risco_churn = num01(a.risco_churn?.noul);
const intencao_compra = num01(a.intencao_compra?.noul);

let faixa = 'humano';
if (valida && rota !== 'indefinido') {
  if (confianca >= LIMIAR_AUTO) faixa = 'automatico';
  else if (confianca >= LIMIAR_S2) faixa = 'sistema_2';
}

let motivo_humano = null;
if (!valida) motivo_humano = res.error ? 'Jev indisponível ou erro HTTP' : 'resposta fora do contrato';
else if (rota === 'indefinido') motivo_humano = 'conversa sem informação suficiente';

const alertas = [];
if ((risco_churn ?? 0) >= LIMIAR_ALERTA) alertas.push('evasao');
if ((intencao_compra ?? 0) >= LIMIAR_ALERTA) alertas.push('comercial');

const prioridade = urgencia === null ? 'P2' : urgencia >= 3 ? 'P1' : urgencia >= 1.5 ? 'P2' : 'P3';

return {
  json: {
    aluno_id: req.aluno_id,
    canal: req.canal,
    ultima_mensagem: req.ultima_mensagem,
    rota,
    confianca,
    faixa,
    motivo_humano,
    prioridade,
    urgencia,
    risco_churn,
    intencao_compra,
    alertas,
    probabilidades_rota: valida ? a.rota.probabilities : null,
    modelo: res.model ?? null,
    tokens_entrada: res.usage?.input_tokens ?? res.usage?.prompt_tokens ?? null,
    decidido_em: new Date().toISOString()
  }
};

